import random
import sys
from decimal import Decimal

sys.path.insert(0, "/tmp/<path>")
sys.path.insert(0, "/tmp/<path>")

import legacy_pricing  # noqa: E402
import pricing  # noqa: E402

TIERS = [None, "silver", "platinum", "bronze", "", "SILVER", ["x"], {"a": 1}]
CATEGORIES = [None, "books", "food", "toys", "default", "", ["books"], 3]
COUPONS = [None, "WELCOME5", "HALFSHIP", "PCT10", "PCT0", "PCT45", "PCT-5", "PCTx", "BOGUS", ""]
QTYS = [-3, 0, 1, 2, 9, 10, 11, 25, 1000]


def random_price(rng: random.Random) -> object:
    kind = rng.randrange(5)
    if kind == 0:
        return rng.randrange(0, 500)
    if kind == 1:
        return f"{rng.randrange(0, 100000)}.{rng.randrange(100):02d}"
    if kind == 2:
        return rng.uniform(0, 300)  # float goes through str()
    if kind == 3:
        return f"{rng.randrange(10**15, 10**17)}.{rng.randrange(10**6):06d}"
    return f"{rng.randrange(1, 9)}.{rng.randrange(1000):03d}5"


def random_cart(rng: random.Random) -> list[dict[str, object]]:
    cart = []
    for i in range(rng.randrange(0, 6)):
        item: dict[str, object] = {"sku": f"S{i}", "price": random_price(rng)}
        item["qty"] = rng.choice(QTYS)
        if rng.random() < 0.8:
            item["category"] = rng.choice(CATEGORIES)
        cart.append(item)
    return cart


def outcome(fn, *args):  # type: ignore[no-untyped-def]
    try:
        return ("ok", fn(*args))
    except Exception as exc:  # comparing error behaviour on purpose
        return ("err", type(exc).__name__, str(exc))


def main() -> None:
    rng = random.Random(12345)
    mismatches = 0
    cases = 0
    for _ in range(20000):
        cart = random_cart(rng)
        customer: dict[str, object] = {}
        if rng.random() < 0.9:
            customer["tier"] = rng.choice(TIERS)
        coupon = rng.choice(COUPONS)
        cases += 1
        old = outcome(legacy_pricing.checkout, cart, customer, coupon)
        new = outcome(pricing.checkout, cart, customer, coupon)
        if repr(old) != repr(new):
            mismatches += 1
            if mismatches <= 5:
                print("MISMATCH", cart, customer, coupon, "\n  old", old, "\n  new", new)
    # Bad input shapes must fail identically too.
    for bad in [[{"sku": "A", "price": "x", "qty": 1}], [{"sku": "A", "price": 1, "qty": 1.5}],
                [{"price": 1, "qty": 1}], [{"sku": "A", "price": 1, "qty": "2"}]]:
        cases += 1
        old = outcome(legacy_pricing.checkout, bad, {})
        new = outcome(pricing.checkout, bad, {})
        if repr(old) != repr(new):
            mismatches += 1
            print("MISMATCH (bad input)", bad, "\n  old", old, "\n  new", new)
    print(f"cases={cases} mismatches={mismatches}")
    print("gold 100 x1:", pricing.checkout([{"sku": "G", "price": "100", "qty": 1}], {"tier": "gold"}))


if __name__ == "__main__":
    main()

